                ''
                'requests==2.31.0'
                'flask>=2.0.0'
                'certifi'
            ) | Set-Content -Path $tempFile
            $script:reqFixture = $tempFile
        }

        AfterAll {
            Remove-Item -Path $script:reqFixture -ErrorAction SilentlyContinue
        }

